async function handleConvertVideo(request, sendNotification) {
  const { path, format } = request.params.arguments;
  const progressToken = request.params._meta?.progressToken;
  const chunks = await splitIntoChunks(path);

  for (let i = 0; i < chunks.length; i++) {
    await encodeChunk(chunks[i], format);

    if (progressToken) {
      await sendNotification({
        method: "notifications/progress",
        params: {
          progressToken,
          progress: i + 1,
          total: chunks.length,
          message: `Encoded chunk ${i + 1} of ${chunks.length}`
        }
      });
    }
  }

  return {
    content: [{ type: "text", text: "Video converted successfully" }]
  };
}

async def handle_run_search(request, send_notification):
    query = request.params["arguments"]["query"]
    progress_token = request.params.get("_meta", {}).get("progressToken")
    pages = await get_search_pages(query)

    results = []
    for i, page in enumerate(pages):
        found = await scan_page(page, query)
        results.extend(found)

        if progress_token:
            await send_notification({
                "method": "notifications/progress",
                "params": {
                    "progressToken": progress_token,
                    "progress": i + 1,
                    "total": len(pages),
                    "message": f"Scanned page {i + 1} of {len(pages)}"
                }
            })

    return {"content": [{"type": "text", "text": f"Found {len(results)} matches"}]}

async function callToolWithTimeout(session, name, args, timeoutMs = 60000) {
  const progressToken = crypto.randomUUID();
  let lastActivity = Date.now();

  session.onProgress(progressToken, () => {
    lastActivity = Date.now();
  });

  const resultPromise = session.request("tools/call", {
    name,
    arguments: args,
    _meta: { progressToken }
  });

  const watchdog = setInterval(() => {
    if (Date.now() - lastActivity > timeoutMs) {
      session.cancel(progressToken);
    }
  }, 1000);

  try {
    return await resultPromise;
  } finally {
    clearInterval(watchdog);
  }
}

